import{_t as e,at as t,et as n,it as r,n as i,ot as a,rt as o,xt as s}from"./chunks/framework.Ke88N3OB.js";var c=JSON.parse(`{"title":"DynamicLightsPumpkin","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/packages/dynamic-lights-pumpkin/docs/index.md"},"headers":[],"relativePath":"packages/dynamic-lights-pumpkin/docs/index.md","filePath":"packages/dynamic-lights-pumpkin/docs/index.md","lastUpdated":1792508971000}`),l={name:`packages/dynamic-lights-pumpkin/docs/index.md`},u={id:`dynamiclightspumpkin`,tabindex:`-1`,class:`component-page-title`},d={class:`component-page-title__version`,href:`https://github.com/filiphsps/pumpkin-plugins/releases/tag/dynamic-lights-pumpkin-v0.1.0`,"aria-label":`Release v0.1.0`};function f(i,c,l,f,p,m){let h=s(`Badge`);return e(),o(`div`,null,[n(`h1`,u,[c[0]||=n(`img`,{class:`component-page-title__icon`,src:`/pumpkin-plugins/packages/dynamic-lights-pumpkin/icon.svg`,alt:``,"aria-hidden":`true`,width:`48`,height:`48`},null,-1),c[1]||=n(`span`,{class:`component-page-title__text`},[t(`DynamicLightsPumpkin `),n(`a`,{class:`header-anchor`,href:`#dynamiclightspumpkin`,"aria-label":`Permalink to “DynamicLightsPumpkin”`},`​`)],-1),n(`a`,d,[a(h,{type:`info`,text:`v0.1.0`})])]),c[2]||=r(`<p>DynamicLightsPumpkin gives players temporary light from supported held items, dropped items, and configured entity types. It sends light-block changes to each player&#39;s client; it doesn&#39;t change the server world. These lights are temporary and may disappear when the client reloads the area. The light from a held item is shown only to the player holding it; other players don&#39;t see it.</p><p>The plugin supports Java Edition only. Pumpkin sends client-only block changes only to Java clients, so Bedrock players get no light.</p><p>Install <code>dynamic-lights-pumpkin.wasm</code> in the Pumpkin server&#39;s <code>plugins/</code> directory and restart. On first load, grant the plugin data-folder permissions in the server console. Players can run <code>/dynamiclights</code> to turn the effect on or off for themselves; that choice is remembered across restarts.</p><h2 id="light-sources" tabindex="-1">Light sources <a class="header-anchor" href="#light-sources" aria-label="Permalink to “Light sources”">​</a></h2><p>The generated <code>config.toml</code> lists the built-in item sources. Remove an entry or set its <code>light_level</code> to <code>0</code> to disable it, or add an item ID with a level from <code>0</code> to <code>15</code>. Items in either hand can provide light; when both qualify, the brighter one wins. See <a href="./configuration">Configure light sources</a> for the item and entity settings.</p><p>Entity lighting is enabled by default and also covers dropped items. Every 10 ticks, the plugin checks configured entity types within 15 blocks of each player along each axis, then sends changes when a light moves, changes level, or leaves range. You can change the refresh interval in the configuration; longer intervals mean less frequent checks and less smooth movement. Dropped items use the matching held-item level when the plugin sees them spawn or can identify a player&#39;s drop. It skips ambiguous drops and items already on the ground when the plugin starts.</p><h2 id="updates-and-recovery" tabindex="-1">Updates and recovery <a class="header-anchor" href="#updates-and-recovery" aria-label="Permalink to “Updates and recovery”">​</a></h2><p>Player movement within the same block doesn&#39;t move a light. After item, inventory, teleport, respawn, or world-change events, the plugin checks the completed state on the next tick. Turning the effect off or unloading the plugin restores the real blocks to the affected clients. A recovery reader also repairs temporary light levels left in the server world by an earlier plugin version.</p>`,8)])}var p=i(l,[[`render`,f]]);export{c as __pageData,p as default};